using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class FinishRoleSurface {public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit required");const string root="Assets/ShooterSurvival/Models/Chapters/Chapters45/DetailedCharacters20261003/",backup="outputs/chapter45-detailed-design-2026-10-03/recovery/role-surface-pass";if(Directory.Exists(backup))throw new Exception("Already applied");Directory.CreateDirectory(backup);var shader=Shader.Find("FlatKit/Stylized Surface");if(shader==null)throw new Exception("Missing shader");var rows=new List<object>();foreach(var id in new[]{"CH01","CH02","CH03","CH04R","CH05","CH06R","CH07","CH08","CH09","CH10"}){string path=root+id+"/character.mat";File.Copy(path,backup+"/"+id+".mat",false);var mat=AssetDatabase.LoadAssetAtPath<Material>(path);mat.shader=shader;EditorUtility.SetDirty(mat);string texture=AssetDatabase.GetAssetPath(mat.GetTexture("_BaseMap"));File.Copy(texture+".meta",backup+"/"+id+".texture.meta",false);var ti=(TextureImporter)AssetImporter.GetAtPath(texture);ti.isReadable=false;ti.SaveAndReimport();rows.Add(new{id,shader=mat.shader.name,mipmaps=ti.mipmapEnabled,readable=ti.isReadable,memory=UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(AssetDatabase.LoadAssetAtPath<Texture2D>(texture))});}AssetDatabase.SaveAssets();return new{items=rows,reason="Identical native poses isolate black tears to the inverted-hull outline pass; preserve FlatKit surface shading and texture. Disable CPU texture duplicate after import."};}}
